int64_t orca_process_start(int pid) {
#ifdef __APPLE__
  struct kinfo_proc info;
  size_t size = sizeof(info);
  int mib[] = {CTL_KERN, KERN_PROC, KERN_PROC_PID, pid};
  if (sysctl(mib, 4, &info, &size, NULL, 0) != 0) return -1;
  if (size == 0) return 0;
