		Args:  cobra.MinimumNArgs(1),
		ValidArgsFunction: func(
			cobraCmd *cobra.Command, args []string, toComplete string,
		) ([]string, cobra.ShellCompDirective) {
			return completion.GetWorkspaceSuggestions(
				cobraCmd.Root(), cmd.Context, cmd.Provider, args, toComplete, cmd.Owner,
			)
		},
		RunE: func(cobraCmd *cobra.Command, args []string) error {
			ctx := cobraCmd.Context()

			dash := cobraCmd.ArgsLenAtDash()
			var nameArgs, cmdArgs []string
			if dash >= 0 {
				nameArgs = args[:dash]
				cmdArgs = args[dash:]
			} else {
				cmdArgs = args
			}

			if len(nameArgs) > 1 {
				return fmt.Errorf("expected at most one workspace name, got %d", len(nameArgs))
			}
			if len(nameArgs) == 1 {
				cmd.WorkspaceName = nameArgs[0]
			}
			if len(cmdArgs) == 0 {
				return fmt.Errorf("a command to execute is required after --")
			}

			return cmd.Run(ctx, cmdArgs)
		},
	}

	cliflags.Add(execCmd,
		cliflags.String(&cmd.WorkspaceFolder, names.WorkspaceFolder, "",
			"Path to the workspace folder"),
		cliflags.String(&cmd.ContainerID, names.ContainerID, "",
			"Target a specific container by ID"),
		cliflags.String(&cmd.DockerPath, names.DockerPath, "",
			"Path to the docker/podman executable (defaults to 'docker')"),
		cliflags.StringSlice(&cmd.RemoteEnv, names.RemoteEnv, nil,
			"Environment variables to set in the container (KEY=VALUE format)"),
		cliflags.Bool(&cmd.SkipPostCreate, names.SkipPostCreate, false,
			"Skip running postCreateCommand"),
	)
	cliflags.RegisterDevContainerModifierFlags(execCmd.Flags(), cliflags.DevContainerModifierFlags{
		UserEnvProbe:        &cmd.DefaultUserEnvProbe,
		IDLabels:            &cmd.IDLabels,
		ContainerDataFolder: &cmd.ContainerDataFolder,
	})

	return execCmd
}

func (cmd *ExecCmd) Run(ctx context.Context, args []string) error {
	cmd.warnUnsupportedFlags()

	if err := cmd.validateExecFlags(); err != nil {
		return err
	}
	reporter, err := newWorkspaceStatusReporter(
		cmd.ResultFormat,
		os.Stderr,
		cmd.Verbosity > 0 || cmd.Debug,
	)
	if err != nil {
		return err
	}
	cmd.statusReporter = reporter

	// Must run before the container-id branch below, else name+container-id would
	// silently take the container path instead of erroring.
	if cmd.WorkspaceName != "" && (cmd.WorkspaceFolder != "" || cmd.ContainerID != "") {
		return errFolderNameConflict
	}

	if cmd.ContainerID != "" {
		return cmd.runWithContainerID(ctx, args)
	}

	return cmd.runWithWorkspace(ctx, args)
}

func (cmd *ExecCmd) warnUnsupportedFlags() {
	if cmd.ContainerDataFolder != "" {
		log.Warnf("--container-data-folder is accepted but not yet implemented for exec")
	}
	if cmd.SkipPostCreate {
		log.Warnf("--skip-post-create is accepted but not yet implemented for exec")
	}
}

