        check_tunnel(saved, directory)
        true
      } catch {
        _ => false
      }
      if ready {
        if waiting {
          save_diagnostic(
            "ssh-channel",
            "recovered",
            tunnel_directory=directory,
            recording=workspace_recording(state),
          )
        }
        return ssh_mux_options(saved, directory)
      }
      if !waiting {
        waiting = true
        save_diagnostic(
          "ssh-channel",
          "waiting",
          tunnel_directory=directory,
          recording=workspace_recording(state),
        )
      }
      @async.sleep(500)
    } nobreak {
      abort("unreachable")
    }
