    quote(uid) +
    " > \"$root/.owner\"; fi; " +
    "chown \"$(id -u " +
    quote(user) +
    "):\"\"$(id -g " +
    quote(user) +
    ")\" \"$root\"; chmod 700 \"$root\""
  ignore(
    devsy(
      state,
      [
        "workspace",
        "ssh",
        required(state, "workspaceId"),
        "--start-services=false",
        "--agent-forwarding=false",
        "--user",
        "root",
        "--command",
        script,
      ],
      "orca-storage",
    ),
  )
  save_diagnostic(
    "orca-storage",
    "success",
    source=Storage(volume, required(state, "projectRoot")),
    recording=workspace_recording(state),
  )
}

