#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <stdint.h>
#include <string.h>
extern int64_t orca_process_start(int);
extern int orca_group_exists(int);
extern int orca_transport_input_closed(int);
int main(void) {
  int input[2],output[2]; if(pipe(input)||pipe(output)) return 2;
  int pid=fork(); if(pid<0) return 3;
  if(!pid) {
    if(setsid()<0) _exit(4);
    dup2(input[0],0);close(input[0]);close(input[1]);close(output[0]);
    char buffer[5];if(read(0,buffer,5)!=5) _exit(5);
    write(output[1],buffer,5);
    while(1) pause();
  }
  close(input[0]);close(output[1]);
  usleep(100000);
  if(orca_transport_input_closed(pid)!=0) return 6;
  char buffer[5];write(input[1],"SSH\000x",5);
  if(read(output[0],buffer,5)!=5||memcmp(buffer,"SSH\000x",5)) return 7;
  close(input[1]);usleep(100000);
  int eof=orca_transport_input_closed(pid);
  kill(-pid,SIGKILL);usleep(100000);
  long long birth=orca_process_start(pid);int group=orca_group_exists(pid);
  int status;waitpid(pid,&status,0);close(output[0]);
  printf("Linux transport: binary data preserved; peer_closed=%d terminated_birth=%lld live_group=%d\n",eof,birth,group);
  return eof==1 && birth==0 && group==0 ? 0 : 8;
}

